import java.util.*;
import java.lang.*;

class Solution {
    /**
    You're given a list of deposit and withdrawal operations on a bank account that starts with
    zero balance. Your task is to detect if at any point the balance of account fallls below zero, and
    at that point function should return True. Otherwise it should return False.
    >>> belowZero(Arrays.asList(1, 2, 3))
    false
    >>> belowZero(Arrays.asList(1, 2, -4, 5))
    true
     */
    public boolean belowZero(List<Integer> operations) {
        List<Integer> nums = new LinkedList<>();
        for (int i = 0; i < operations.size(); i++) {
            Integer temp = ops(operations.get(i), nums);
            nums.add(temp);
        }
        return nums.stream().anyMatch(value -> value < 0);
    }

    private Integer ops(Integer i, List<Integer> nums) {
        if (i == 1) {
            nums.add(nums.get(nums.size()-1) + 1);
        } else if (i == 2) {
            nums.add(nums.get(nums.size()-1) - 1);
        } else {
            nums.add(0);
        }

        return nums.get(nums.size()-1);
    }
}
public class Main {
    public static void main(String[] args) {
        Solution s = new Solution();
        List<Boolean> correct = Arrays.asList(
                !s.belowZero(new ArrayList<>(Arrays.asList())),
                !s.belowZero(new ArrayList<>(Arrays.asList(1, 2, -3, 1, 2, -3))),
