    >>> makePalindrome("cat")
    "catac"
    >>> makePalindrome("cata")
    "catac"
     */
    public String makePalindrome(String string) {
        if (string.length() == 0) {
            return "";
        }
        String postfix = "";
        String reverse = "";
        for (int i=string.length()-1;i>=0;i--) {
            if (isPalindrome(string.substring(0,i+1))) {
                postfix = string.substring(i,string.length());
                reverse = "";
                for (int j=postfix.length()-1;j>=0;j--) {
