class Solution {
    /**
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
     */
    public int startsOneEnds(int n) {
        if (n < 1) return 0;
        int count = 0;
        int mod = (int) Math.pow(10, n);
        int sum = 0;
        for (int i = 1; i <= mod; i++) {
            int temp = i;
            int j = 0;
            while (temp > 0) {
                int d = temp % 10;
                temp /= 10;
                if (j == n) {
                    if (d == 1) {
                        count++;
                    }
                    else {
                        sum += count;
                        count = 0;
                    }
                }
                j++;
            }
        }
        return sum;
    }
