class Solution {
    /**
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> orderByPoints(Arrays.asList(1, 11, -1, -11, -12)) == [-1, -11, 1, -12, 11]
    >>> orderByPoints(Arrays.asList()) == []
     */
    public List<Integer> orderByPoints(List<Integer> nums) {
        ArrayList<Integer> sortedNums = new ArrayList<Integer>();

        // Sort the numbers
        nums.sort((a,b)->{return (a+""+b).compareTo((b+""+a));});

        // Create a map of the sum of digits for each number
        // and then sort them
        Map<Integer, Integer> sums = new HashMap<Integer, Integer>();

        for (int num : nums) {
            int sum = 0;
            int remainder = num;
            while (remainder > 0) {
                sum += remainder % 10;
                remainder = remainder / 10;
            }

            sums.put(num, sum);
        }

        int[] keys = sums.keySet().toArray(new Integer[sums.size()]);
        Arrays.sort(keys);

        for (int key : keys) {
            sortedNums.add(key);
        }

        return sortedNums;
    }
}
